class State:
    __slots__ = ["candidate", "votes", "last_vote"]

    def __init__(self, cand, votes, last):
        self.candidate = cand
        self.votes = votes
        self.last_vote = last

    def beats(self, other, extra):
        return self.votes + extra > other.votes


def main():
