def generatePrimeFactors():
    factor[1] = 1
    for i in range(2, MAX):
        factor[i] = i
    for i in range(4, MAX, 2):
        factor[i] = 2
    i = 3
    while i * i < MAX:
        if factor[i] == i:
            j = i * i
            while j < MAX:
                if factor[j] == j:
                    factor[j] = i
                j += i
        i += 1


def calculateNoOFactors(n):
    if n == 1:
        return 1
    ans = 1
    dup = factor[n]
    c = 1
    j = int(n / factor[n])
    while j > 1:
        if factor[j] == dup:
            c += 1
        else:
            dup = factor[j]
            ans = ans * (c + 1)
            c = 1
        j = int(j / factor[j])
    ans = ans * (c + 1)
    return ans


def calc(n):
    dp = [-1] * (n + 1)
    dp[0] = 1
    dp[1] = 1
    pre = 2
    generatePrimeFactors()
    for i in range(2, n + 1):
        dp[i] = pre + calculateNoOFactors(i) - 1
        pre += dp[i]
    return (dp[n]) % 998244353


