def binom(n, k):
    if k > n - k:
        return binom(n, n - k)
    res = 1
    for i in range(k):
        res = res * (n - i) // (i + 1)
    return res


def comp_ones_vecs(k, n):
    if k < n:
        return 0
    ans = 0
    for Z in range(n):
        ans += (-1) ** Z * binom(n, Z) * (n - Z) ** k
    return ans // factorial(n)


