class smt:
    def __init__(self, l, r, arr):
        self.l = l
        self.r = r
        self.value = (1 << 31) - 1 if l < r else arr[l]
        mid = (l + r) // 2
        if l < r:
            self.left = smt(l, mid, arr)
            self.right = smt(mid + 1, r, arr)
            self.value &= self.left.value & self.right.value

    def setvalue(self, x, val):
        if self.l == self.r:
            self.value = val
            return
        mid = (self.l + self.r) // 2
        if x <= mid:
            self.left.setvalue(x, val)
        else:
            self.right.setvalue(x, val)
        self.value = self.left.value & self.right.value

    def ask(self, l, r):
        if l <= self.l and r >= self.r:
            return self.value
        val = (1 << 31) - 1
        mid = (self.l + self.r) // 2
        if l <= mid:
            val &= self.left.ask(l, r)
        if r > mid:
            val &= self.right.ask(l, r)
        return val


class DSU:
    def __init__(self, n):
        self.c = [-1] * n

    def same(self, x, y):
        return self.find(x) == self.find(y)

    def find(self, x):
        if self.c[x] < 0:
            return x
        self.c[x] = self.find(self.c[x])
        return self.c[x]

    def union(self, u, v):
        u, v = self.find(u), self.find(v)
        if u == v:
            return False
        if self.c[u] < self.c[v]:
            u, v = v, u
        self.c[u] += self.c[v]
        self.c[v] = u
        return True

    def size(self, x):
        return -self.c[self.find(x)]


class UFS:
    def __init__(self, n):
        self.parent = [i for i in range(n)]
        self.ranks = [0] * n

    def find(self, x):
        if x != self.parent[x]:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, u, v):
        pu, pv = self.find(u), self.find(v)
        if pu == pv:
            return False
        if self.ranks[pu] >= self.ranks[pv]:
            self.parent[pv] = pu
            if self.ranks[pv] == self.ranks[pu]:
                self.ranks[pu] += 1
        else:
            self.parent[pu] = pv


def Prime(n):
    c = 0
    prime = []
    flag = [0] * (n + 1)
    for i in range(2, n + 1):
        if not flag[i]:
            prime.append(i)
            c += 1
        for j in range(c):
            if i * prime[j] > n:
                break
            flag[i * prime[j]] = prime[j]
            if i % prime[j] == 0:
                break
    return prime


