def hitLotery(n):
    lst = [-1 for i in range(n + 1)]
    lst[0] = 0
    i = 1
    while i < len(lst):
        b1 = lst[i - 1]
        if i - 5 >= 0:
            b2 = lst[i - 5]
        else:
            b2 = sys.maxsize
        if i - 10 >= 0:
            b3 = lst[i - 10]
        else:
            b3 = sys.maxsize
        if i - 20 >= 0:
            b4 = lst[i - 20]
        else:
            b4 = sys.maxsize
        if i - 100 >= 0:
            b5 = lst[i - 100]
        else:
            b5 = sys.maxsize
        lst[i] = 1 + min(b1, b2, b3, b4, b5)
        i = i + 1
    return lst[n]


