from typing import List


class Solution:
    def calculate(cls, weight_combo: List[str]) -> str:
        mapping = defaultdict(int)
        for combo in weight_combo:
            [first_op, operator, second_op] = list(combo)
            if operator == ">":
                mapping[first_op] += 1
